walkthrough.code:
-- Sargable: a range scan on the B-tree
CREATE INDEX events_occurred_at ON events (occurred_at);
SELECT count(*) FROM events
WHERE occurred_at >= timestamptz '2024-03-01 00:00:00+00'
  AND occurred_at <  timestamptz '2024-03-02 00:00:00+00';

-- A hot JSON field promoted to a real column
ALTER TABLE orders
  ADD COLUMN status text GENERATED ALWAYS AS (doc->>'status') STORED;
CREATE INDEX orders_status ON orders (status);

SELECT o.id, item->>'sku' AS sku, coalesce((item->>'qty')::int, 1) AS qty
FROM orders o
CROSS JOIN LATERAL jsonb_array_elements(
  CASE WHEN jsonb_typeof(o.doc->'items') = 'array' THEN o.doc->'items' ELSE '[]'::jsonb END
) AS item
WHERE item->>'sku' IS NOT NULL;

