  id           int PRIMARY KEY,
  email        text,
  signed_up_at timestamptz NOT NULL
);

CREATE TABLE orders (
  id        int PRIMARY KEY,
  placed_at timestamptz NOT NULL,
  doc       jsonb NOT NULL
);

